// GENERATED by tools/gen-samples.mjs from samples/ - do not edit.
(function (RC) {
  RC.SAMPLE_FILES = {
 "HELLO.BAS": "' HELLO.BAS - your first program!\n' Press F5 to run it. Change the words and run it again.\nCLS\nCOLOR 14\nPRINT \"Hello! Welcome to BASIC.\"\nCOLOR 7\nPRINT\nINPUT \"What is your name\"; name$\nPRINT\nFOR i = 1 TO 5\n    COLOR i + 9\n    PRINT \"Nice to meet you, \"; name$; \"!\"\nNEXT i\nCOLOR 7\nPRINT\nPRINT \"Try the Examples button for games, graphics and music.\"\nEND\n",
 "SAMPLES\\CLASSIC.BAS": "10 REM CLASSIC.BAS - A GW-BASIC style program with line numbers\n20 REM Concepts: GOTO, GOSUB/RETURN, READ/DATA, ON...GOTO, string functions\n30 CLS : KEY OFF\n40 PRINT \"*** STATES AND CAPITALS QUIZ ***\"\n50 PRINT\n60 SCORE = 0 : Q = 0\n70 READ STATE$, CAP$\n80 IF STATE$ = \"END\" THEN GOTO 200\n90 Q = Q + 1\n100 PRINT \"What is the capital of \"; STATE$;\n110 INPUT A$\n120 IF UCASE$(LEFT$(A$, 4)) = UCASE$(LEFT$(CAP$, 4)) THEN GOSUB 300 ELSE GOSUB 400\n130 GOTO 70\n200 PRINT : PRINT \"You scored\"; SCORE; \"out of\"; Q\n210 R = INT(SCORE / Q * 3) + 1\n220 ON R GOTO 230, 240, 250, 250\n230 PRINT \"Keep studying!\" : END\n240 PRINT \"Not bad!\" : END\n250 PRINT \"Geography genius!\" : END\n300 SCORE = SCORE + 1 : PRINT \"  Correct!\" : RETURN\n400 PRINT \"  Sorry, it's \"; CAP$ : RETURN\n500 DATA France, Paris, Japan, Tokyo, Kenya, Nairobi\n510 DATA Peru, Lima, Canada, Ottawa, END, END\n",
 "SAMPLES\\CLOCK.BAS": "' CLOCK.BAS - An analog clock driven by ON TIMER events\n' Concepts: ON TIMER(n) GOSUB, TIMER ON, TIME$, CIRCLE, trig, event handlers\nSCREEN 12\nCONST PI = 3.14159265#\ncx = 320: cy = 230: r = 180\nCIRCLE (cx, cy), r + 10, 7\nFOR h = 1 TO 12\n    a = h * PI / 6\n    LOCATE INT((cy - (r - 15) * COS(a)) / 16) + 1, INT((cx + (r - 15) * SIN(a)) / 8): PRINT LTRIM$(STR$(h));\nNEXT\nON TIMER(1) GOSUB Tick\nTIMER ON\nGOSUB Tick\nLOCATE 29, 25: PRINT \"Press any key to stop\";\nDO: LOOP WHILE INKEY$ = \"\"\nTIMER OFF\nEND\n\nTick:\n    t$ = TIME$\n    hh = VAL(LEFT$(t$, 2)) MOD 12: mm = VAL(MID$(t$, 4, 2)): ss = VAL(RIGHT$(t$, 2))\n    CIRCLE (cx, cy), r - 25, 0, , , 1: PAINT (cx, cy), 0, 0\n    CIRCLE (cx, cy), r - 25, 8\n    DrawHand (hh + mm / 60) * PI / 6, r * .5, 15\n    DrawHand (mm + ss / 60) * PI / 30, r * .75, 11\n    DrawHand ss * PI / 30, r * .8, 12\n    LOCATE 2, 36: PRINT t$\n    RETURN\n\nSUB DrawHand (a, length, colr)\n    SHARED cx, cy\n    LINE (cx, cy)-(cx + length * SIN(a), cy - length * COS(a)), colr\nEND SUB\n",
 "SAMPLES\\COLORS.BAS": "' COLORS.BAS - The 16 text colors and box-drawing characters\nSCREEN 0: WIDTH 80: CLS\nCOLOR 15, 1\nLOCATE 2, 20: PRINT CHR$(201); STRING$(38, 205); CHR$(187)\nLOCATE 3, 20: PRINT CHR$(186); \"      TEXT MODE COLOR CHART         \"; CHR$(186)\nLOCATE 4, 20: PRINT CHR$(200); STRING$(38, 205); CHR$(188)\nCOLOR 7, 0\nFOR fg = 0 TO 15\n    LOCATE 6 + fg, 10\n    COLOR 7, 0: PRINT USING \"COLOR ## \"; fg;\n    COLOR fg, 0: PRINT STRING$(10, 219); \" \";\n    COLOR fg, 7: PRINT \" Sample \";\n    COLOR fg + 16, 0: PRINT \" Blinking \";\nNEXT fg\nCOLOR 7, 0\nLOCATE 23, 10: PRINT \"Background colors: \";\nFOR bg = 0 TO 7: COLOR 15, bg: PRINT bg; : NEXT\nCOLOR 7, 0: PRINT\n",
 "SAMPLES\\DIARY.BAS": "' DIARY.BAS - Keep a diary in a text file\n' Concepts: OPEN ... FOR APPEND / INPUT, PRINT #, LINE INPUT #, EOF, DATE$, TIME$\nCLS\nPRINT \"My Diary (stored in DIARY.TXT - see it in the Files panel!)\"\nPRINT\nON ERROR GOTO NoFile\nOPEN \"DIARY.TXT\" FOR INPUT AS #1\nPRINT \"Previous entries:\"\nCOLOR 11\nDO WHILE NOT EOF(1)\n    LINE INPUT #1, l$\n    PRINT \"  \"; l$\nLOOP\nCLOSE #1\nCOLOR 7\nContinue:\nON ERROR GOTO 0\nPRINT\nLINE INPUT \"Write today's entry (Enter to skip): \"; e$\nIF e$ <> \"\" THEN\n    OPEN \"DIARY.TXT\" FOR APPEND AS #1\n    PRINT #1, DATE$; \" \"; LEFT$(TIME$, 5); \"  \"; e$\n    CLOSE #1\n    PRINT \"Saved.\"\nEND IF\nEND\n\nNoFile:\n    PRINT \"(no diary yet - this will be the first entry)\"\n    RESUME Continue\n",
 "SAMPLES\\FACTORL.BAS": "' FACTORL.BAS - Recursion and the debugger\n' 1. Click the gutter next to the line marked <-- to set a breakpoint (or press F9 there).\n' 2. Press F5. When it stops, open the Call Stack and Variables panels.\n' 3. Click different frames: each one has its own n%!\n' 4. Press F8 to step, F10 to step over, Shift+F8 to step out.\n' 5. Double-click a variable's value to change it while paused.\nDECLARE FUNCTION Factorial# (n%)\nDECLARE FUNCTION Fib& (n%)\nCLS\nFOR i% = 0 TO 12\n    PRINT USING \"##_! = ###,###,###\"; i%; Factorial#(i%)\nNEXT\nPRINT\nPRINT \"Fibonacci numbers:\";\nFOR i% = 1 TO 15: PRINT Fib&(i%); : NEXT\nPRINT\n\nFUNCTION Factorial# (n%)\n    IF n% <= 1 THEN\n        Factorial# = 1            ' <-- try a breakpoint here\n    ELSE\n        Factorial# = n% * Factorial#(n% - 1)\n    END IF\nEND FUNCTION\n\nFUNCTION Fib& (n%)\n    IF n% < 3 THEN Fib& = 1 ELSE Fib& = Fib&(n% - 1) + Fib&(n% - 2)\nEND FUNCTION\n",
 "SAMPLES\\GUESS.BAS": "' GUESS.BAS - Guess the number\n' Concepts: RANDOMIZE, RND, INPUT, DO...LOOP, IF...ELSEIF\nRANDOMIZE TIMER\nCLS\nPRINT \"I'm thinking of a number between 1 and 100.\"\nsecret = INT(RND * 100) + 1\ntries = 0\nDO\n    INPUT \"Your guess\"; guess\n    tries = tries + 1\n    IF guess < secret THEN\n        PRINT \"  Too low!\"\n    ELSEIF guess > secret THEN\n        PRINT \"  Too high!\"\n    END IF\nLOOP UNTIL guess = secret\nPRINT\nPRINT \"You got it in\"; tries; \"tries!\"\nIF tries <= 7 THEN PRINT \"Excellent guessing!\" ELSE PRINT \"Hint: try halving the range each time.\"\n",
 "SAMPLES\\HANOI.BAS": "' HANOI.BAS - Towers of Hanoi: the classic recursion example\n' TRY THIS: set a breakpoint (F9) on the \"Move\" line, run, and open the Call Stack\n' panel. Watch the stack grow and shrink as the recursion unfolds!\nDECLARE SUB Solve (n AS INTEGER, from AS INTEGER, dest AS INTEGER, via AS INTEGER)\nDECLARE SUB Move (from AS INTEGER, dest AS INTEGER)\nDECLARE SUB DrawAll ()\nDIM SHARED pegs(1 TO 3, 1 TO 10) AS INTEGER, h(1 TO 3) AS INTEGER, moves AS LONG\nCONST DISKS = 5\nSCREEN 12\nFOR i = DISKS TO 1 STEP -1: h(1) = h(1) + 1: pegs(1, h(1)) = i: NEXT\nDrawAll\nSLEEP 1\nSolve DISKS, 1, 3, 2\nLOCATE 28, 30: PRINT \"Solved in\"; moves; \"moves!\"\nSLEEP\n\nSUB DrawAll\n    LINE (0, 120)-(639, 440), 0, BF\n    FOR p = 1 TO 3\n        x = p * 160\n        LINE (x - 3, 200)-(x + 3, 400), 6, BF\n        FOR k = 1 TO h(p)\n            w = pegs(p, k) * 12\n            LINE (x - w, 400 - k * 18)-(x + w, 400 - k * 18 + 15), pegs(p, k) + 8, BF\n        NEXT\n    NEXT\n    LINE (40, 401)-(600, 410), 6, BF\n    LOCATE 3, 30: PRINT \"Moves:\"; moves; \"   \"\nEND SUB\n\nSUB Move (from AS INTEGER, dest AS INTEGER)\n    h(dest) = h(dest) + 1\n    pegs(dest, h(dest)) = pegs(from, h(from))\n    h(from) = h(from) - 1\n    moves = moves + 1\n    DrawAll\n    SOUND 300 + dest * 200, .5\nEND SUB\n\nSUB Solve (n AS INTEGER, from AS INTEGER, dest AS INTEGER, via AS INTEGER)\n    IF n = 0 THEN EXIT SUB\n    Solve n - 1, from, via, dest\n    Move from, dest\n    Solve n - 1, via, dest, from\nEND SUB\n",
 "SAMPLES\\LIFE.BAS": "' LIFE.BAS - Conway's Game of Life in text mode\nDEFINT A-Z\nCONST W = 78, H = 22\nDIM g(0 TO W + 1, 0 TO H + 1), n(0 TO W + 1, 0 TO H + 1)\nRANDOMIZE TIMER\nFOR y = 1 TO H: FOR x = 1 TO W: g(x, y) = (RND < .3): NEXT: NEXT\nCLS\ngen = 0\nDO\n    FOR y = 1 TO H\n        LOCATE y + 1, 2\n        row$ = \"\"\n        FOR x = 1 TO W\n            IF g(x, y) THEN row$ = row$ + CHR$(254) ELSE row$ = row$ + \" \"\n        NEXT\n        COLOR 10: PRINT row$;\n    NEXT\n    gen = gen + 1\n    COLOR 15: LOCATE 1, 2: PRINT \"Generation\"; gen; \" (any key to stop)\";\n    FOR y = 1 TO H: FOR x = 1 TO W\n        c = 0\n        FOR dy = -1 TO 1: FOR dx = -1 TO 1\n            IF dx OR dy THEN IF g(x + dx, y + dy) THEN c = c + 1\n        NEXT: NEXT\n        n(x, y) = (c = 3) OR (g(x, y) AND c = 2)\n    NEXT: NEXT\n    FOR y = 1 TO H: FOR x = 1 TO W: g(x, y) = n(x, y): NEXT: NEXT\nLOOP WHILE INKEY$ = \"\"\nCOLOR 7\n",
 "SAMPLES\\MANDEL.BAS": "' MANDEL.BAS - The Mandelbrot set in 320x200x256 (SCREEN 13)\n' Concepts: nested loops, floating point, programming the VGA palette with OUT\nDEFINT I, P, X, Y\nSCREEN 13\n' Build a smooth blue-to-gold palette in DAC registers 1..63\nFOR i = 1 TO 63\n    OUT &H3C8, i\n    OUT &H3C9, i \\ 2: OUT &H3C9, i \\ 3: OUT &H3C9, 63 - i \\ 2\n    OUT &H3C8, i + 64\n    OUT &H3C9, 63: OUT &H3C9, 32 + i \\ 2: OUT &H3C9, i \\ 4\nNEXT\nmaxIter = 120\nFOR y = 0 TO 199\n    ci! = (y - 100) / 80\n    FOR x = 0 TO 319\n        cr! = (x - 210) / 100\n        zr! = 0: zi! = 0: iter = 0\n        DO WHILE iter < maxIter AND zr! * zr! + zi! * zi! < 4\n            t! = zr! * zr! - zi! * zi! + cr!\n            zi! = 2 * zr! * zi! + ci!\n            zr! = t!\n            iter = iter + 1\n        LOOP\n        IF iter = maxIter THEN PSET (x, y), 0 ELSE PSET (x, y), 1 + (iter * 3) MOD 127\n    NEXT x\nNEXT y\nSLEEP\n",
 "SAMPLES\\MODES.BAS": "' MODES.BAS - A tour of every screen mode. Press a key to advance.\nDECLARE SUB Demo (m%, w%, h%, colors%, txt$)\nDemo 1, 320, 200, 4, \"CGA 4-color\"\nDemo 2, 640, 200, 2, \"CGA hi-res mono\"\nDemo 3, 720, 348, 2, \"Hercules mono\"\nDemo 7, 320, 200, 16, \"EGA 16-color\"\nDemo 8, 640, 200, 16, \"EGA 16-color\"\nDemo 9, 640, 350, 16, \"EGA 16 of 64\"\nDemo 10, 640, 350, 4, \"EGA monochrome\"\nDemo 11, 640, 480, 2, \"VGA mono\"\nDemo 12, 640, 480, 16, \"VGA 16-color\"\nDemo 13, 320, 200, 256, \"VGA 256-color\"\nSCREEN 0: WIDTH 80: PRINT \"That's all the modes!\"\n\nSUB Demo (m%, w%, h%, colors%, txt$)\n    SCREEN m%\n    n% = colors%: IF n% > 16 THEN n% = 16\n    bw% = w% \\ n%\n    FOR c% = 0 TO n% - 1\n        LINE (c% * bw%, h% \\ 2)-((c% + 1) * bw% - 1, h% - 1), c%, BF\n    NEXT\n    IF colors% > 16 THEN FOR c% = 16 TO 255: LINE (c% - 16 + 32, h% \\ 2 - 30)-(c% - 16 + 32, h% \\ 2 - 5), c%: NEXT\n    CIRCLE (w% \\ 2, h% \\ 4), h% \\ 6, colors% - 1\n    LINE (0, 0)-(w% - 1, h% - 1), colors% - 1, B\n    LOCATE 2, 2: PRINT \"SCREEN\"; m%; \"-\"; w%; \"x\"; h%\n    LOCATE 3, 2: PRINT txt$\n    SLEEP\nEND SUB\n",
 "SAMPLES\\MULTI\\MAIN.BAS": "' MULTI\\MAIN.BAS - A program split across several files\n'  * '$INCLUDE: pulls in declarations and code from SHAPES.BI\n'  * CHAIN runs another program, passing COMMON variables\n' $INCLUDE: 'SHAPES.BI'\nCOMMON SHARED player$, score%\nCLS\nplayer$ = \"Ada\": score% = 42\nPRINT \"Area of a 3x4 rectangle:\"; RectArea(3, 4)\nPRINT \"Area of a circle, r=2:  \"; CircleArea(2)\nPRINT\nPRINT \"Now CHAINing to PART2.BAS with player$ and score%...\"\nSLEEP 2\nCHAIN \"PART2.BAS\"\n",
 "SAMPLES\\MULTI\\PART2.BAS": "' PART2.BAS - started by CHAIN from MAIN.BAS\nCOMMON SHARED player$, score%\nPRINT\nPRINT \"Hello from PART2.BAS!\"\nPRINT \"COMMON variables arrived: player$ = \"; player$; \", score% =\"; score%\n",
 "SAMPLES\\MULTI\\SHAPES.BI": "' SHAPES.BI - included by MAIN.BAS with '$INCLUDE\nDECLARE FUNCTION RectArea! (w!, h!)\nDECLARE FUNCTION CircleArea! (r!)\nCONST PI = 3.14159\n\nFUNCTION RectArea! (w!, h!)\n    RectArea! = w! * h!\nEND FUNCTION\n\nFUNCTION CircleArea! (r!)\n    CircleArea! = PI * r! * r!\nEND FUNCTION\n",
 "SAMPLES\\MUSIC.BAS": "' MUSIC.BAS - The PC speaker plays music with PLAY (Music Macro Language)\n' O=octave  L=note length  T=tempo  < > change octave  P=pause  MS/ML/MN=staccato/legato/normal\nCLS\nPRINT \"Ode to Joy (Beethoven)\"\nPLAY \"T140 O3 L4 EEFG GFED CCDE E.D8D2\"\nPLAY \"EEFG GFED CCDE D.C8C2\"\nPRINT \"A scale, staccato then legato\"\nPLAY \"MS T200 O3 L8 CDEFGAB>C\"\nPLAY \"ML <CBAGFEDC\"\nPRINT \"Sound effects with SOUND frequency, duration\"\nFOR f = 200 TO 1200 STEP 100: SOUND f, 1: NEXT\nFOR f = 1200 TO 200 STEP -100: SOUND f, 1: NEXT\nPRINT \"Twinkle Twinkle, in the background (MB) while we count:\"\nPLAY \"MB T120 O3 L4 CCGGAAG2FFEEDDC2\"\nFOR i = 1 TO 8: PRINT i; : SLEEP 1: NEXT\nPRINT\nPRINT \"Done!\"\n",
 "SAMPLES\\PHONEBK.BAS": "' PHONEBK.BAS - A tiny phone book stored in a RANDOM-access file\n' Concepts: TYPE records, OPEN ... FOR RANDOM, GET/PUT, LOF, SELECT CASE menu\nTYPE Contact\n    nm AS STRING * 20\n    phone AS STRING * 14\nEND TYPE\nDIM c AS Contact\nOPEN \"PHONES.DAT\" FOR RANDOM AS #1 LEN = LEN(c)\nDO\n    count = LOF(1) \\ LEN(c)\n    CLS\n    COLOR 14: PRINT \"PHONE BOOK\"; : COLOR 7: PRINT \" (\"; LTRIM$(STR$(count)); \" entries, stored in PHONES.DAT)\"\n    PRINT\n    PRINT \"1) List   2) Add   3) Find   4) Quit\"\n    INPUT \"Choice\"; ch$\n    SELECT CASE ch$\n        CASE \"1\"\n            FOR i = 1 TO count\n                GET #1, i, c\n                PRINT USING \"### \"; i; : PRINT c.nm; c.phone\n            NEXT\n            PRINT : PRINT \"Press a key\"; : SLEEP\n        CASE \"2\"\n            LINE INPUT \"Name : \"; n$\n            LINE INPUT \"Phone: \"; p$\n            c.nm = n$: c.phone = p$\n            PUT #1, count + 1, c\n        CASE \"3\"\n            LINE INPUT \"Search for: \"; s$\n            found = 0\n            FOR i = 1 TO count\n                GET #1, i, c\n                IF INSTR(UCASE$(c.nm), UCASE$(s$)) THEN PRINT c.nm; c.phone: found = found + 1\n            NEXT\n            PRINT found; \"found. Press a key\"; : SLEEP\n    END SELECT\nLOOP UNTIL ch$ = \"4\"\nCLOSE #1\nPRINT \"Goodbye!\"\n",
 "SAMPLES\\PLASMA.BAS": "' PLASMA.BAS - Palette rotation: the picture is drawn once, then only colors change\n' Concepts: SCREEN 13, OUT to VGA DAC ports, WAIT for vertical retrace, INKEY$\nDEFINT A-Z\nSCREEN 13\nFOR y = 0 TO 199\n    FOR x = 0 TO 319\n        v! = SIN(x / 16) + SIN(y / 11) + SIN((x + y) / 23) + SIN(SQR((x - 160) ^ 2 + (y - 100) ^ 2) / 9)\n        PSET (x, y), 1 + INT((v! + 4) * 31.75) MOD 255\n    NEXT\nNEXT\nLOCATE 25, 2: PRINT \"Palette cycling - press any key\";\nDIM r(255), g(255), b(255)\nFOR i = 1 TO 255\n    r(i) = INT(31.5 + 31.5 * SIN(i * 6.2832 / 255))\n    g(i) = INT(31.5 + 31.5 * SIN(i * 6.2832 / 255 + 2.094))\n    b(i) = INT(31.5 + 31.5 * SIN(i * 6.2832 / 255 + 4.188))\nNEXT\nshift = 0\nDO\n    WAIT &H3DA, 8\n    OUT &H3C8, 1\n    FOR i = 1 TO 255\n        j = 1 + (i + shift) MOD 255\n        OUT &H3C9, r(j): OUT &H3C9, g(j): OUT &H3C9, b(j)\n    NEXT\n    shift = (shift + 2) MOD 255\nLOOP WHILE INKEY$ = \"\"\nSCREEN 0: WIDTH 80\n",
 "SAMPLES\\SIERPIN.BAS": "' SIERPIN.BAS - The chaos game: random jumps draw an ordered fractal\nSCREEN 12\nRANDOMIZE TIMER\nDIM vx(2), vy(2)\nvx(0) = 320: vy(0) = 20: vx(1) = 40: vy(1) = 460: vx(2) = 600: vy(2) = 460\nx = 320: y = 240\nFOR i = 1 TO 60000\n    v = INT(RND * 3)\n    x = (x + vx(v)) / 2: y = (y + vy(v)) / 2\n    PSET (x, y), 10 + v\n    IF INKEY$ <> \"\" THEN EXIT FOR\nNEXT\nLOCATE 2, 2: PRINT \"Sierpinski triangle from 60,000 random jumps\"\nSLEEP\n",
 "SAMPLES\\SNAKE.BAS": "' SNAKE.BAS - Eat the stars, don't bite yourself!\n' Keys: arrow keys to steer, Esc to quit.\n' Concepts: arrays as a queue, INKEY$ extended keys, TIMER delays, SOUND, SCREEN function\nDEFINT A-Z\nDECLARE SUB PlaceFood ()\nDIM SHARED sx(1000), sy(1000), fx, fy\nRANDOMIZE TIMER\nCLS\nCOLOR 9: LOCATE 1, 1: PRINT STRING$(80, 177)\nFOR r = 2 TO 23: LOCATE r, 1: PRINT CHR$(177); : LOCATE r, 80: PRINT CHR$(177); : NEXT\nLOCATE 24, 1: PRINT STRING$(80, 177);\nhead = 3: tail = 1: dx = 1: dy = 0: grow = 0: score = 0\nFOR i = 1 TO 3: sx(i) = 38 + i: sy(i) = 12: LOCATE 12, 38 + i: COLOR 10: PRINT CHR$(219); : NEXT\nPlaceFood\ndelay! = .09\nDO\n    t! = TIMER\n    DO\n        k$ = INKEY$\n        IF k$ = CHR$(27) THEN EXIT DO\n        IF LEN(k$) = 2 THEN\n            SELECT CASE ASC(RIGHT$(k$, 1))\n                CASE 72: IF dy = 0 THEN dx = 0: dy = -1\n                CASE 80: IF dy = 0 THEN dx = 0: dy = 1\n                CASE 75: IF dx = 0 THEN dx = -1: dy = 0\n                CASE 77: IF dx = 0 THEN dx = 1: dy = 0\n            END SELECT\n        END IF\n    LOOP WHILE TIMER - t! < delay! AND TIMER >= t!\n    IF k$ = CHR$(27) THEN EXIT DO\n    nx = sx(head) + dx: ny = sy(head) + dy\n    c = SCREEN(ny, nx)\n    IF c = 177 OR c = 219 THEN EXIT DO\n    head = head MOD 1000 + 1: sx(head) = nx: sy(head) = ny\n    COLOR 10: LOCATE ny, nx: PRINT CHR$(219);\n    IF nx = fx AND ny = fy THEN\n        score = score + 10: grow = grow + 3: SOUND 880, 1\n        IF delay! > .03 THEN delay! = delay! - .004\n        PlaceFood\n    END IF\n    IF grow > 0 THEN\n        grow = grow - 1\n    ELSE\n        LOCATE sy(tail), sx(tail): PRINT \" \";\n        tail = tail MOD 1000 + 1\n    END IF\n    COLOR 15: LOCATE 25, 2: PRINT \"Score:\"; score;\nLOOP\nSOUND 110, 6\nCOLOR 12: LOCATE 12, 33: PRINT \" GAME  OVER \";\nCOLOR 7: LOCATE 25, 40: PRINT \"Final score:\"; score;\nEND\n\nSUB PlaceFood\n    DO\n        fx = INT(RND * 77) + 2: fy = INT(RND * 21) + 2\n    LOOP UNTIL SCREEN(fy, fx) = 32\n    COLOR 14: LOCATE fy, fx: PRINT \"*\";\nEND SUB\n",
 "SAMPLES\\SORTS.BAS": "' SORTS.BAS - Watch bubble sort and selection sort work, bar by bar\n' Tip: change the speed with the toolbar Speed menu, or try \"Animate execution\".\nDECLARE SUB DrawBar (i%)\nDECLARE SUB Shuffle ()\nDEFINT A-Z\nCONST N = 64\nDIM SHARED a(1 TO N)\nSCREEN 13\nShuffle\nLOCATE 1, 1: PRINT \"Bubble sort\"\nFOR i = N TO 2 STEP -1\n    FOR j = 1 TO i - 1\n        IF a(j) > a(j + 1) THEN SWAP a(j), a(j + 1): DrawBar j: DrawBar j + 1\n    NEXT\nNEXT\nSLEEP 1\nShuffle\nLOCATE 1, 1: PRINT \"Selection sort\"\nFOR i = 1 TO N - 1\n    m = i\n    FOR j = i + 1 TO N: IF a(j) < a(m) THEN m = j\n    NEXT\n    SWAP a(i), a(m): DrawBar i: DrawBar m\n    FOR d = 1 TO 2000: NEXT\nNEXT\nLOCATE 1, 1: PRINT \"Sorted! Press a key.\"\nSLEEP\n\nSUB DrawBar (i)\n    x = (i - 1) * 5\n    LINE (x, 20)-(x + 3, 199), 0, BF\n    LINE (x, 199 - a(i) * 2.7)-(x + 3, 199), 32 + a(i) MOD 72, BF\nEND SUB\n\nSUB Shuffle\n    RANDOMIZE TIMER\n    FOR i = 1 TO N: a(i) = i: NEXT\n    FOR i = N TO 2 STEP -1: SWAP a(i), a(INT(RND * i) + 1): NEXT\n    CLS\n    FOR i = 1 TO N: DrawBar i: NEXT\nEND SUB\n",
 "SAMPLES\\SPIRAL.BAS": "' SPIRAL.BAS - Colorful spirals in 640x480 VGA (SCREEN 12)\nSCREEN 12\nCONST PI = 3.14159265#\ncx = 320: cy = 240\nFOR k = 0 TO 5\n    a0 = k * PI / 3\n    PSET (cx, cy)\n    FOR t = 0 TO 12 * PI STEP .05\n        r = t * 6\n        x = cx + r * COS(t + a0)\n        y = cy + r * SIN(t + a0) * .9\n        LINE -(x, y), (k MOD 15) + 9\n    NEXT t\nNEXT k\nCOLOR 15\nLOCATE 29, 2: PRINT \"SCREEN 12: 640 x 480, 16 colors.  Press any key.\";\nSLEEP\n",
 "SAMPLES\\SPRITES.BAS": "' SPRITES.BAS - Flicker-free animation with GET/PUT sprites and page flipping\n' Concepts: SCREEN 7 with 2 pages (draw on page 1 while showing page 0), PCOPY, GET, PUT\nDEFINT A-Z\nSCREEN 7, 0, 1, 0\nDIM ball(200)\nCIRCLE (8, 8), 7, 14: PAINT (8, 8), 12, 14\nCIRCLE (6, 6), 2, 15: PAINT (6, 6), 15, 15\nGET (0, 0)-(16, 16), ball\nCONST NB = 6\nDIM x(NB), y(NB), dx(NB), dy(NB)\nRANDOMIZE TIMER\nFOR i = 1 TO NB\n    x(i) = RND * 280 + 10: y(i) = RND * 150 + 10\n    dx(i) = INT(RND * 5) - 2: IF dx(i) = 0 THEN dx(i) = 3\n    dy(i) = INT(RND * 5) - 2: IF dy(i) = 0 THEN dy(i) = -2\nNEXT\nDO\n    CLS\n    LINE (0, 0)-(319, 199), 9, B\n    LOCATE 24, 2: PRINT \"Page flipping demo - any key quits\";\n    FOR i = 1 TO NB\n        x(i) = x(i) + dx(i): y(i) = y(i) + dy(i)\n        IF x(i) < 2 OR x(i) > 300 THEN dx(i) = -dx(i)\n        IF y(i) < 2 OR y(i) > 170 THEN dy(i) = -dy(i)\n        PUT (x(i), y(i)), ball, PSET\n    NEXT\n    PCOPY 1, 0\n    WAIT &H3DA, 8\nLOOP WHILE INKEY$ = \"\"\nSCREEN 0: WIDTH 80\n",
 "SAMPLES\\TIMESTBL.BAS": "' TIMESTBL.BAS - Multiplication table with PRINT USING\nCLS\nCOLOR 15: PRINT \"     \";\nFOR c = 1 TO 12: PRINT USING \"####\"; c; : NEXT: PRINT\nCOLOR 8: PRINT \"     \"; STRING$(48, 196)\nFOR r = 1 TO 12\n    COLOR 15: PRINT USING \"## \"; r; : COLOR 8: PRINT CHR$(179); \" \";\n    FOR c = 1 TO 12\n        IF r = c THEN COLOR 14 ELSE COLOR 7\n        PRINT USING \"####\"; r * c;\n    NEXT c\n    PRINT\nNEXT r\nCOLOR 7\n",
 "SAMPLES\\TURTLE.BAS": "' TURTLE.BAS - Turtle-style drawing with the DRAW macro language\n' U/D/L/R/E/F/G/H move, B = move without drawing, N = return after move,\n' C = color, S = scale, TA = turn angle, M = move to x,y, P = paint\nSCREEN 12\nDRAW \"BM320,240\"\nFOR i = 0 TO 35\n    DRAW \"C\" + STR$(9 + i MOD 7) + \" TA\" + STR$(i * 10) + \" NU120 NR40\"\nNEXT\n' A star, step by step\nDRAW \"BM120,120 C14 S4\"\nFOR i = 1 TO 5\n    DRAW \"TA\" + STR$((i * 144) MOD 360) + \" U60\"\nNEXT\n' A little house\nDRAW \"BM480,380 C10 TA0 U60 E30 F30 D60 L60 BE10 P2,10\"\nCOLOR 15: LOCATE 29, 2: PRINT \"DRAW: a whole drawing language inside BASIC!\";\nSLEEP\n"
};
})(RC);
